import type { AppIcon } from "apps";

// Generated by scripts/icon.ts from Simple Icons (CC0) "spotify".
export const icons: readonly AppIcon[] = [
  {
    "src": "data:image/svg+xml;base64,",
    "mimeType": "image/svg+xml",
    "theme": "light"
  },
  {
    "src": "data:image/svg+xml;base64,",
    "mimeType": "image/svg+xml",
    "theme": "dark"
  }
];

import {
  accountRouter,
  decodeJson,
  defineApp,
  defineProvider,
  json,
  oauth2,
  object,
  router,
  string,
  withApprovals,
} from "apps";
import { always } from "apps/operations/approval";
import { liveOpenapiRouter } from "apps/openapi";
import { icons } from "./icon.js";
import { options } from "./openapi.js";

// Spotify answers null for a missing display name, so these are read as JSON and checked.
const Me = object({ id: string(), display_name: json().optional(), email: json().optional() });

/** Trimmed text, or undefined when blank or not text. */
const shown = (value: unknown) =>
  typeof value === "string" && value.trim() ? value.trim() : undefined;

const spotify = defineProvider({
  name: "Spotify",
  hosts: ["api.spotify.com", "accounts.spotify.com"],
  auth: {
    // Spotify has no dynamic client registration: the connect page asks for an app's client.
    oauth: oauth2({
      authorizationUrl: "https://accounts.spotify.com/authorize",
      tokenUrl: "https://accounts.spotify.com/api/token",
      tokenEndpointAuthMethod: "client_secret_basic",
      scopes: [
        "user-read-private",
        "user-read-email",
        "user-library-read",
        "user-library-modify",
        "playlist-read-private",
        "playlist-read-collaborative",
        "playlist-modify-public",
        "playlist-modify-private",
        "user-follow-read",
        "user-follow-modify",
        "user-top-read",
        "user-read-recently-played",
        "user-read-playback-position",
        "user-read-playback-state",
        "user-read-currently-playing",
        "user-modify-playback-state",
        "ugc-image-upload",
      ],
    }),
  },
  async health({ account, fetch, signal }) {
    const response = await fetch("https://api.spotify.com/v1/me", {
      signal,
      headers: { Authorization: `Bearer ${account.fields.access_token}`, Accept: "application/json" },
    });
    const me = await decodeJson(response, Me);
    // The account reads as the person: their email, else their display name. Spotify's user id is
    // an opaque string for most accounts, so it identifies the account but never names it.
    // Names fit the host's 255 characters; a cut email would name someone else, so it is left out.
    const email = shown(me.email);
    const displayName = shown(me.display_name)?.slice(0, 255);
    return {
      accountInfo: {
        externalId: me.id,
        ...(email === undefined || email.length > 255 ? {} : { email }),
        ...(displayName === undefined ? {} : { displayName }),
        profileUrl: `https://open.spotify.com/user/${me.id}`,
      },
    };
  },
});

export default defineApp(
  { user: { accounts: { spotify: spotify.many() } }, icons },
  async ({ user, cache, fetch, signal }) => ({
    tools: router(
      await accountRouter(
        user?.accounts.spotify ?? [],
        (account) =>
          withApprovals(liveOpenapiRouter({ ...options, cache, fetch, signal, account }), (tool) =>
            tool.kind === "mutation" ? always() : undefined,
          ),
        { signal },
      ),
      {
        title: "Spotify",
        description:
          "Search the catalog, read and edit playlists and the saved library, and control playback through the Spotify Web API.",
        icons,
      },
    ),
  }),
);

import type { OpenapiToolNamesOptions } from "apps/openapi";

// Spotify's document declares one OAuth 2.0 scheme, "oauth_2_0"; the access token is sent as a bearer token.
export const options = {
  source: { url: "https://developer.spotify.com/reference/web-api/open-api-schema.yaml" },
  allowedOrigin: "https://api.spotify.com",
  securitySchemes: { oauth_2_0: { type: "http", scheme: "bearer" } },
  methods: {
    oauth: [{ scheme: "oauth_2_0", field: "access_token", part: "value", prefix: "" }],
  },
  oauth: [],
} satisfies OpenapiToolNamesOptions;

{
  "name": "@executor.sh/spotify",
  "description": "Search the catalog, read and edit playlists and the saved library, and control playback through the Spotify Web API.",
  "private": true,
  "type": "module",
  "executor": {
    "title": "Spotify"
  },
  "dependencies": {
    "apps": "0.0.1-beta.104-basalt.11"
  }
}
